<div class="panel"><p class="eyebrow">ACCOUNT HISTORY</p><h2>Recent transactions</h2><table class="table"><tr><th>Date</th><th>Reference</th><th>Description</th><th>Amount</th><th>Status</th></tr><?php foreach($transactions as $transaction):?><tr><td><?=date('M j, Y',strtotime($transaction['created_at']))?></td><td><?=html_escape($transaction['reference'])?></td><td><?=html_escape($transaction['description'])?></td><td><?=$transaction['direction']==='credit'?'+':'-'?>$<?=number_format($transaction['amount'],2)?></td><td><span class="badge <?=$transaction['status']?>"><?=$transaction['status']?></span></td></tr><?php endforeach;?></table></div>
